#pragma once
#include "video_encoder.hpp"
#include <fstream>
#include <iomanip>
inline std::string json_quote(const std::string& text){std::string out="\"";for(const auto c:text){if(c=='\\'||c=='\"'){out+='\\';out+=c;}else if(c=='\n')out+="\\n";else if(c=='\r')out+="\\r";else if(c=='\t')out+="\\t";else if(static_cast<unsigned char>(c)>=32)out+=c;}return out+'\"';}
inline void write_recording_report(const std::filesystem::path& file,const aibs::recording::RecordingReport& r){
 std::ofstream o(file);o<<std::setprecision(17)<<"{\"started\":"<<r.started<<",\"finished\":"<<r.finished<<",\"failed\":"<<r.failed<<",\"quarantined\":"<<r.quarantined<<",\"width\":"<<r.width<<",\"height\":"<<r.height<<",\"target_fps\":"<<r.target_fps<<",\"encoder_exit_code\":"<<r.encoder_exit_code<<",\"frames_received\":"<<r.frames_received<<",\"frames_written\":"<<r.frames_written<<",\"dropped_for_rate\":"<<r.dropped_for_rate<<",\"missed_capture_slots\":"<<r.missed_capture_slots<<",\"backpressure_events\":"<<r.backpressure_events<<",\"repeated_at_stop\":"<<r.repeated_at_stop<<",\"encoder_frame_capacity\":"<<r.encoder_frame_capacity<<",\"encoder_frame_capacity_active\":"<<r.encoder_frame_capacity_active<<",\"producer_frame_capacity_peak\":"<<r.producer_frame_capacity_peak<<",\"timestamp_capacity_bytes\":"<<r.timestamp_capacity_bytes<<",\"encoder_peak_working_set_bytes\":"<<r.encoder_peak_working_set_bytes<<",\"encoder_sampled_private_bytes_peak\":"<<r.encoder_sampled_private_bytes_peak<<",\"wall_seconds\":"<<r.wall_seconds<<",\"first_frame_seconds\":"<<r.first_frame_seconds<<",\"last_frame_seconds\":"<<r.last_frame_seconds<<",\"total_write_seconds\":"<<r.total_write_seconds<<",\"hardware_probe_seconds\":"<<r.hardware_probe_seconds<<",\"hardware_probe_attempted\":"<<r.hardware_probe_attempted<<",\"hardware_probe_passed\":"<<r.hardware_probe_passed<<",\"hardware_probe_exit_code\":"<<r.hardware_probe_exit_code<<",\"requested_encoder\":"<<json_quote(r.requested_encoder)<<",\"fallback_reason\":"<<json_quote(r.fallback_reason)<<",\"hardware_probe_stderr\":"<<json_quote(r.hardware_probe_stderr)<<",\"maximum_write_seconds\":"<<r.maximum_write_seconds<<",\"encoder\":"<<json_quote(r.encoder)<<",\"timing\":"<<json_quote(r.timing)<<",\"error\":"<<json_quote(r.error)<<",\"encoder_stderr\":"<<json_quote(r.encoder_stderr)<<",\"timestamps\":[";
 bool first=true;for(const auto& t:r.timestamps){if(!first)o<<',';first=false;o<<"{\"present_id\":"<<t.present_id<<",\"capture_seconds\":"<<t.capture_seconds<<",\"write_complete_seconds\":"<<t.write_complete_seconds<<",\"stop_repeat\":"<<t.stop_repeat<<'}';}o<<"]}";if(!o)throw std::runtime_error("Cannot write recorder test report");
}
